export function message(locale: Locale, key: MessageKey): string {
  return (messages[locale] as Partial<Record<MessageKey, string>>)[key] ?? supplementaryAnalyticsPeriodMessages[locale]?.[key] ?? supplementaryAuthenticatedSessionMessages[locale]?.[key] ?? supplementaryCompanyMessages[locale]?.[key] ?? supplementarySecurityMessages[locale]?.[key] ?? supplementaryTeamMessages[locale]?.[key] ?? supplementaryNavigationMessages[locale]?.[key] ?? supplementaryOverviewMessages[locale]?.[key] ?? supplementaryAuthMessages[locale]?.[key] ?? supplementaryOnboardingMessages[locale]?.[key] ?? supplementaryOnboardingStatus[locale]?.[key] ?? supplementaryDocumentMessages[locale]?.[key] ?? supplementaryDocumentPurposeMessages[locale]?.[key] ?? supplementaryDocumentWorkspaceMessages[locale]?.[key] ?? supplementarySupportMessages[locale]?.[key] ?? supplementarySupportOlderMessages[locale]?.[key] ?? supplementaryManualInvoiceMessages[locale]?.[key] ?? supplementaryManualCounterpartyMessages[locale]?.[key] ?? supplementaryManualStatusMessages[locale]?.[key] ?? supplementarySupplierLogoMessages[locale]?.[key] ?? supplementaryInvoiceDocumentMessages[locale]?.[key] ?? supplementaryRecordDetailMessages[locale]?.[key] ?? supplementaryWorkspaceShellMessages[locale]?.[key] ?? supplementaryOrsOperationsMessages[locale]?.[key] ?? supplementaryOrsFieldMessages[locale]?.[key] ?? supplementaryOrsTableMessages[locale]?.[key] ?? supplementaryOrsFeedbackMessages[locale]?.[key] ?? supplementaryOrsPromptMessages[locale]?.[key] ?? (messages["en-GB"] as Partial<Record<MessageKey,string>>)[key] ?? supplementarySupplierLogoMessages["en-GB"]?.[key] ?? String(key);
}

export function localeDirection(locale: Locale): "ltr" | "rtl" {
  return locale === "ar" || locale === "ur-PK" ? "rtl" : "ltr";
}

export function formatNumber(value: number, locale: Locale, options?: Intl.NumberFormatOptions) {
  return new Intl.NumberFormat(locale, options).format(value);
}

export function formatCurrency(value: number, currency: string, locale: Locale) {
  return new Intl.NumberFormat(locale, { style: "currency", currency }).format(value);
}

export function formatCurrencyString(value:string,currency:string,locale:Locale){
  if(!/^-?\d+(?:\.\d+)?$/.test(value))return value;
  try{
    const negative=value.startsWith("-"),absolute=negative?value.slice(1):value,[whole,fraction=""]=absolute.split("."),formatter=new Intl.NumberFormat(locale,{style:"currency",currency}),digits=formatter.resolvedOptions().maximumFractionDigits??2;
    if(fraction.length>digits)return value;
    const integer=new Intl.NumberFormat(locale,{useGrouping:true,maximumFractionDigits:0}).format(BigInt(whole));
    const localizedFraction=digits?new Intl.NumberFormat(locale,{useGrouping:false,minimumIntegerDigits:digits,maximumFractionDigits:0}).format(BigInt(fraction.padEnd(digits,"0")||"0")):"";
    const template=formatter.formatToParts(negative?-1234.5:1234.5);let inserted=false;
    return template.map(part=>{
      if(part.type==="integer"){if(inserted)return "";inserted=true;return integer;}
      if(part.type==="group")return "";
      if(part.type==="fraction")return localizedFraction;
      if(part.type==="decimal"&&!digits)return "";
      return part.value;
    }).join("");
  }catch{return value;}
}

export function formatDate(value: Date | string | number, locale: Locale, options?: Intl.DateTimeFormatOptions) {
  const date=typeof value==="string"&&/^\d{4}-\d{2}-\d{2}$/.test(value)?new Date(`${value}T12:00:00`):new Date(value);
  return new Intl.DateTimeFormat(locale, options).format(date);
}
